import{_ as t,o,c as u,ag as q}from"./chunks/framework.DaAXJYxM.js";const d=JSON.parse('{"title":"第74章 数","description":"","frontmatter":{},"headers":[],"relativePath":"第74章_数.md","filePath":"第74章_数.md"}'),e={name:"第74章_数.md"};function a(_,p,r,n,s,c){return o(),u("div",null,[...p[0]||(p[0]=[q('<h1 id="第74章-数" tabindex="-1">第74章 数 <a class="header-anchor" href="#第74章-数" aria-label="Permalink to &quot;第74章 数&quot;">​</a></h1><p>那年暑假我把她说过多少次&quot;以后&quot;，数了一遍。</p><p>起因很无聊。</p><p>七月里我们这边热，实验室不开，我在宿舍。郑拓回家，屋里剩我一个人。</p><p>我一个人待着的时候，我必须找一件事干。</p><p>我找的是那个文件。</p><p>我二月把它导出来过一次，一共四个多月的记录。我把那个文件打开，从头往下翻，翻的时候我拿一支笔，一沓纸。</p><p>我在纸上写一个字：后。</p><p>她每讲一次&quot;以后&quot;，我划一道。</p><p>我原以为这个数不会很大。</p><p>我数完是二百九十三道。</p><p>我坐在那儿看了这个数很久。</p><p>二百九十三。</p><p>四月到七月，实际上她说过的&quot;以后&quot;比这还多，因为有几条她发完又抽回去。我这边只能看见一行系统提示：对方撤回了一条消息。我数过那些提示，一共四十六条。</p><p>我第一反应是高兴。</p><p>高兴的原因很龌龊：我想，这么多以后，说明她一直在往前规划，规划里有我。</p><p>然后我做了一件更细的事。</p><p>我把这二百九十三条分成两类。</p><p>一类，&quot;以后&quot;后面跟的主语是&quot;我们&quot;。</p><p>一类，主语是&quot;我&quot;。</p><p>分完我数出来：</p><p>她讲&quot;以后我要&quot;，一百七十四次。</p><p>她讲&quot;以后我能&quot;，四十九次。</p><p>她讲&quot;以后等我&quot;，十九次。</p><p>她讲&quot;以后再说&quot;&quot;以后别问&quot;这类推开的，四十六次。</p><p>她讲&quot;我们以后&quot;，五次。</p><p>一共五次。</p><p>我把那五次单独抄出来。</p><p>第一次是大二寒假前，她说，我们以后可以在一个城市吃饭。</p><p>第二次是四月，她说，我们以后要是都回国，可以去看一场那样的展。</p><p>第三次是五月，她说，我们以后可以拼一张桌。</p><p>第四次是六月，她说，我们以后能不能不要这么说话。</p><p>第五次也是六月，隔了两天，她说，我们以后你告诉我你要什么。</p><p>我看完了这五条。</p><p>第四条和第五条我看了最久。</p><p>因为第四条那个&quot;以后能不能不要&quot;，它其实是一个否定。</p><p>第五条她要我说我要什么。</p><p>这两条我算过。</p><p>算出来的结果是：这五次里，没有一次是她在往那个以后走。</p><p>四次里她是在说这个以后太难，一次她是在让我说。</p><p>我把笔放下。</p><p>我那天做了一件我到现在也没想明白该不该做的事。</p><p>我拿她给我的那些&quot;以后&quot;，跟我自己给出去的做了一次对照。</p><p>我从头翻我自己的记录。</p><p>我讲&quot;以后&quot;，我数出来是六十一句。</p><p>六十一句里，主语是&quot;我们&quot;的，五十四句。</p><p>也就是说，我这一辈子讲&quot;以后&quot;，讲的全是我们两个。</p><p>而她讲&quot;以后&quot;，讲的全是她自己一个人要爬的那座山。</p><p>那天晚上十一点，她上线了。</p><p>她说，我今天累死了。</p><p>我说，你今天干什么了。</p><p>她说，我在改作品集第二稿，我那个导师让我把第一稿全砍。</p><p>她说，以后我要是能做我想做的东西，我就不改。</p><p>我说，你以后一定会。</p><p>她说，你别老说这个。</p><p>我说，说什么。</p><p>她说，说&quot;我以后一定会&quot;。</p><p>她说，你每次说这句，我就得往下想我要不要跟你解释我为什么不一定。</p><p>我说，那我不说。</p><p>她说，你今天很怪。</p><p>我说，我下午算了一件事。</p><p>她说，算什么。</p><p>我说，算你说了多少次以后。</p><p>她不说话。</p><p>过了很久，她说，你数了。</p><p>我说，我没数。</p><p>她说，你说没数，就是数完了。</p><p>我说，二百九十三。</p><p>她说，你连这个都存下来了。</p><p>我说，我存的是我这边给你的，六十一。</p><p>她那边很久。</p><p>然后她发了一段，我印象很深。</p><p>她说，你把这两堆摆在一起，你是不是觉得我这二百九十三句里面没有你。</p><p>我说，我没这么说。</p><p>她说，你就是这么算的。</p><p>她说，那我告诉你一件事。</p><p>她说，我要是能说&quot;我们以后&quot;，我就说了。</p><p>她说，我说不出来不是因为我心里没有。</p><p>她说，是因为我这一句话一出口，我妈第二天就要问我，你说的这个我们是谁。</p><p>她说，我要是答不上来，我妈就要开始替我安排。</p><p>她说，我讲&quot;以后我要挣钱&quot;，我妈听了高兴。</p><p>她说，我讲&quot;我们以后&quot;，我妈第二天就给我爸打电话。</p><p>她说，所以我这两堆不是一个东西。</p><p>她说，我那一百七十四句&quot;我要&quot;，其实每一句后面都跟着一句我不好讲出来的&quot;为了我们&quot;。</p><p>我说，那你怎么不跟我讲。</p><p>她说，我跟你讲了你就开始数。</p><p>她说，你要是不数，你今天晚上会问我&quot;我今天很累&quot;，我讲&quot;我改了图&quot;，我们就结束了。</p><p>她说，我一讲&quot;我们&quot;，你就要把它变成一个能存的东西。</p><p>她说，我拿什么跟你讲我们。</p><p>我那天晚上没有回她。</p><p>但我做了一个表。</p><p>我把那二百九十三句里能判日期的，单独列出来。</p><p>能判日期的有四十一句。</p><p>比如她说&quot;这个月以后我就好了&quot;，&quot;十月底交完就没事了&quot;，&quot;过了这个展我就睡一觉&quot;。</p><p>四十一句。</p><p>到今天为止，过了时间的有三十七句。</p><p>三十七句里，真发生了的，三句。</p><p>那三句我列在最上面，列完我把它们划掉了。</p><p>因为划掉的时候我发现，剩下的三十四句里有一大部分并不是她骗我。</p><p>她是真的以为能成。</p><p>她在最累的时候算了一个她以为自己做得到的数，然后她没做到。</p><p>我把这个发现写在本子上。</p><p>我写：她不是不守诺。</p><p>我写：她是把自己的命算得太轻。</p><p>写完这一句，我把笔放下。</p><p>因为我忽然想起另一件事。</p><p>我自己那张表上写着三百六十小时、七千六百五十句。</p><p>我把两个表摆在一起看。</p><p>她那一张，是拿自己会的东西去算自己不会的东西。</p><p>我这一张，是拿自己有的命去算一件根本没有日期的事。</p><p>这两张表的毛病是同一个。</p><p>那天晚上我把那张纸叠了两下。</p><p>叠得很整齐。</p><p>我坐在桌前，看着那二百九十三道杠。</p><p>我拿笔在最下面写了一行。</p><p>我写：这里面没有一句是假话。</p><p>我写：它们全部是真的，只是全部不是给我的。</p><p>我坐在床上，看着她最后那一句。</p><p>我后来想了很多年这一句。</p><p>我以为我记，是在珍惜。</p><p>她那边读到的是：我只要写进&quot;我们&quot;这两个字，它第二天就会变成我手上的一张凭证。</p><p>而凭证这个东西，是要人来还的。</p><p>那天夜里我把那沓纸拿起来。</p><p>二百九十三道，六十一句，五次的清单。</p><p>我看了很久。</p><p>我没有撕。</p><p>我把它们对齐，折了两折，塞进本子的最后那页。</p><p>本子最后那页本来就厚了。</p><p>那一页里已经塞着一些别的：一张车票的根，一个瓶盖压出来印子，一片从旧画册上掉下来的纸屑。</p><p>我那天在下面垫了一张新的。</p><p>我写的是我自己那一句：我说&quot;我以后一定会&quot;这一句，我也算过。</p><p>我算的是，我说这句的时候，我知道她做不到。</p>',132)])])}const l=t(e,[["render",a]]);export{d as __pageData,l as default};
